<?php
namespace KaarBooking\Component\KaarBooking\Administrator\View\Livetrips;defined('_JEXEC') or die;
use Joomla\CMS\Component\ComponentHelper;use Joomla\CMS\Factory;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;
final class HtmlView extends BaseHtmlView
{
 public array $items=[];public string $mapsKey='';public int $staleMinutes=5;
 public function display($tpl=null):void{$user=Factory::getApplication()->getIdentity();if(!$user->authorise('kaarbooking.analytics.view','com_kaarbooking')&&!$user->authorise('core.manage','com_kaarbooking'))throw new \RuntimeException('Not authorised',403);$db=Factory::getContainer()->get(\Joomla\Database\DatabaseInterface::class);$latest=$db->getQuery(true)->select('driver_id, MAX(id) AS location_id')->from($db->quoteName('#__kaar_driver_locations'))->group('driver_id');$q=$db->getQuery(true)->select(['d.id AS driver_id','d.display_name','d.online_state','l.latitude','l.longitude','l.accuracy_m','l.recorded_at','r.id AS ride_id','r.dispatch_status','b.reference','b.origin_text','b.destination_text','v.registration_number','s.id AS session_id'])->from($db->quoteName('#__kaar_drivers','d'))->join('LEFT','('.$latest.') latest ON latest.driver_id=d.id')->join('LEFT',$db->quoteName('#__kaar_driver_locations','l').' ON l.id=latest.location_id')->join('LEFT',$db->quoteName('#__kaar_rides','r').' ON r.id=l.ride_id AND r.dispatch_status IN ('.$db->quote('accepted').','.$db->quote('arrived').','.$db->quote('in_progress').')')->join('LEFT',$db->quoteName('#__kaar_bookings','b').' ON b.id=r.booking_id')->join('LEFT',$db->quoteName('#__kaar_vehicles','v').' ON v.id=r.vehicle_id')->join('LEFT',$db->quoteName('#__kaar_api_sessions','s').' ON s.user_id=d.user_id AND s.revoked_at IS NULL AND s.access_expires >= '.$db->quote(Factory::getDate()->toSql()))->where('d.online_state='.$db->quote('online'))->group('d.id,d.display_name,d.online_state,l.latitude,l.longitude,l.accuracy_m,l.recorded_at,r.id,r.dispatch_status,b.reference,b.origin_text,b.destination_text,v.registration_number,s.id')->order('l.recorded_at DESC');$this->items=$db->setQuery($q)->loadAssocList()?:[];$params=ComponentHelper::getParams('com_kaarbooking');$this->mapsKey=$params->get('maps_provider','google')==='google'?trim((string)$params->get('google_maps_browser_key','')):'';$this->staleMinutes=max(1,min(60,(int)$params->get('live_location_stale_minutes',5)));parent::display($tpl);}
}
